import React, { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import axios from "axios";

const CandidateDetail = () => {
  const { id } = useParams();
  const [candidate, setCandidate] = useState(null);

  useEffect(() => {
    axios
      .get(`http://localhost:5000/results/${id}`)
      .then((res) => setCandidate(res.data))
      .catch(() => setCandidate(null));
  }, [id]);

  if (!candidate) {
    return <p className="m-4 text-danger">Candidate not found</p>;
  }

  const rules = candidate.rules || {};

  return (
    <div className="container mt-4">
      <Link to="/results">← Back to Results</Link>

      <h3 className="mt-3">{candidate.filename}</h3>

      <p>
        <strong>Final Score:</strong> {candidate.final_score}%
      </p>
      <p>
        <strong>Status:</strong> {candidate.decision}
      </p>

      <hr />

      <h5>Mandatory Skills</h5>
      <p>Status: {rules.mandatory_skills?.status}</p>

      {rules.mandatory_skills?.missing?.length > 0 && (
        <ul>
          {rules.mandatory_skills.missing.map((s, i) => (
            <li key={i}>{s}</li>
          ))}
        </ul>
      )}

      <hr />

      <h5>Skill Overlap</h5>
      <p>Score: {rules.skill_overlap?.score}%</p>

      {rules.skill_overlap?.matched?.length > 0 && (
        <ul>
          {rules.skill_overlap.matched.map((s, i) => (
            <li key={i}>{s}</li>
          ))}
        </ul>
      )}

      <hr />

      <h5>GitHub</h5>
      <p>{rules.github?.evidence || "Not provided"}</p>
    </div>
  );
};

export default CandidateDetail;
